#!/bin/bash
# register-slurm-tools.sh
#
# Registers Slurm MCP server tools as external MCP tools on the ADEPT Gateway.
# Reads tool definitions from tool_registry.json (generated by generate-registration-schemas.py).
#
# Prerequisites:
#   - ADEPT full stack running (Keycloak, Redis, agent_gateway, etc.)
#   - agentic CLI installed (pip install -e src/)
#   - Slurm MCP server running and reachable from Docker containers
#   - /etc/hosts: 127.0.0.1 keycloak (for JWT issuer match on host-side CLI)
#   - jq installed (for parsing tool_registry.json)
#   - tool_registry.json exists (run: make generate-schemas)
#
# Environment variables:
#   AGENT_GATEWAY_URL   — ADEPT gateway the agentic CLI registers against
#                         Default: http://localhost:8083
#   KEYCLOAK_URL        — Keycloak URL for JWT token acquisition
#                         Default: http://keycloak:8180 (Docker DNS name)
#                         CRITICAL: Must match JWT issuer claim; use service name, not localhost
#   KEYCLOAK_REALM      — Keycloak realm for auth
#                         Default: master
#   SLURM_PROTO         — Protocol: http or https (default: http)
#   SLURM_MCP_HOST      — MCP server hostname (default depends on protocol)
#   SLURM_MCP_PORT      — MCP server port (default depends on protocol)
#   SLURM_CA_CERT       — CA certificate for HTTPS verification
#   ADMIN_USER          — Admin username (default: admin)
#   ADMIN_PASS          — Admin password (default: admin)
#
# Usage:
#   ./scripts/register-slurm-tools.sh              # Register all tools
#   ./scripts/register-slurm-tools.sh deregister    # Remove all tools
#   ./scripts/register-slurm-tools.sh verify        # Check Redis for tools
#   ./scripts/register-slurm-tools.sh help          # Show usage

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------

# ADEPT gateway URL — where the agentic CLI registers tools.
export AGENT_GATEWAY_URL="${AGENT_GATEWAY_URL:-http://localhost:8083}"

# Keycloak configuration — must use Docker service name for JWT issuer match.
export KEYCLOAK_URL="${KEYCLOAK_URL:-http://keycloak:8180}"
export KEYCLOAK_REALM="${KEYCLOAK_REALM:-master}"

SLURM_PROTO="${SLURM_PROTO:-http}"
SLURM_CA_CERT="${SLURM_CA_CERT:-./certs/ca.crt}"
ADMIN_USER="${ADMIN_USER:-admin}"
ADMIN_PASS="${ADMIN_PASS:-admin}"

# MCP endpoint host and port — defaults depend on protocol:
#   HTTP  → direct to MCP server (slurm_mcp_server:8002, same Docker network)
#   HTTPS → through nginx proxy (slurm_nginx_proxy:443, TLS termination)
if [ "$SLURM_PROTO" = "https" ]; then
    SLURM_MCP_HOST="${SLURM_MCP_HOST:-slurm_nginx_proxy}"
    SLURM_MCP_PORT="${SLURM_MCP_PORT:-443}"
else
    SLURM_MCP_HOST="${SLURM_MCP_HOST:-slurm_mcp_server}"
    SLURM_MCP_PORT="${SLURM_MCP_PORT:-8002}"
fi

MCP_URL="${SLURM_PROTO}://${SLURM_MCP_HOST}:${SLURM_MCP_PORT}/mcp"

TOOL_PREFIX="slurm_hpc"

# Docker ENGINE auto-detection
if [ -z "${ENGINE:-}" ]; then
    if docker info >/dev/null 2>&1; then
        ENGINE="docker"
    else
        echo "WARNING: Cannot connect to Docker. Some checks may fail."
        ENGINE="docker"
    fi
fi

# ---------------------------------------------------------------------------
# Tool Registry (JSON file generated by generate-registration-schemas.py)
# ---------------------------------------------------------------------------

REGISTRY_FILE="${SCRIPT_DIR}/tool_registry.json"

if [ ! -f "$REGISTRY_FILE" ]; then
    echo "ERROR: ${REGISTRY_FILE} not found."
    echo "  Generate it first: cd examples/slurm_hpc && make generate-schemas"
    exit 1
fi

if ! command -v jq >/dev/null 2>&1; then
    echo "ERROR: jq is required but not installed."
    echo "  Install: sudo apt-get install jq  (or: brew install jq)"
    exit 1
fi

TOOL_COUNT=$(jq '.tools | length' "$REGISTRY_FILE")

# ---------------------------------------------------------------------------
# Detect agentic CLI
# ---------------------------------------------------------------------------

PROJECT_ROOT="$(cd "$(dirname "$0")/../../.." && pwd)"
AGENTIC_CLI=""

ADEPT_CONDA_PREFIX=""
if [ -n "${CONDA_PREFIX:-}" ]; then
    ADEPT_CONDA_PREFIX="$CONDA_PREFIX"
elif command -v conda >/dev/null 2>&1; then
    ADEPT_CONDA_PREFIX="$(conda env list 2>/dev/null | awk '/adept-session/{print $NF}')"
fi

for candidate in \
    "${PROJECT_ROOT}/.venv311/bin/agentic" \
    "${PROJECT_ROOT}/.venv/bin/agentic" \
    "${ADEPT_CONDA_PREFIX:+${ADEPT_CONDA_PREFIX}/bin/agentic}" \
    "$(command -v agentic 2>/dev/null || true)"; do
    if [ -n "$candidate" ] && [ -x "$candidate" ]; then
        AGENTIC_CLI="$candidate"
        break
    fi
done

if [ -z "$AGENTIC_CLI" ]; then
    echo "ERROR: agentic CLI not found."
    echo "  Install: conda activate adept-session && cd ${PROJECT_ROOT} && pip install -e src/"
    exit 1
fi

# Clear cached admin token if it has the wrong issuer
CACHE_FILE="${HOME}/.adept-agentic/cache/admin_token.json"
if [ -f "$CACHE_FILE" ]; then
    CACHED_ISSUER=$(python3 -c "
import json, base64, sys
try:
    with open('$CACHE_FILE') as f:
        d = json.load(f)
    parts = d['access_token'].split('.')
    payload = json.loads(base64.urlsafe_b64decode(parts[1] + '=='))
    print(payload.get('iss', ''))
except: pass
" 2>/dev/null || true)
    EXPECTED_ISSUER="${KEYCLOAK_URL}/realms/${KEYCLOAK_REALM}"
    if [ -n "$CACHED_ISSUER" ] && [ "$CACHED_ISSUER" != "$EXPECTED_ISSUER" ]; then
        echo "  Clearing stale cached token (issuer=$CACHED_ISSUER, expected=$EXPECTED_ISSUER)"
        rm -f "$CACHE_FILE"
    fi
fi

echo "Configuration:"
echo "  KEYCLOAK_URL:       ${KEYCLOAK_URL}"
echo "  AGENT_GATEWAY_URL:  ${AGENT_GATEWAY_URL}"
echo "  SLURM_PROTO:        ${SLURM_PROTO}"
echo "  MCP_URL:            ${MCP_URL}"
echo "  TOOL_PREFIX:        ${TOOL_PREFIX}"
echo "  TOOL_COUNT:         ${TOOL_COUNT} (from tool_registry.json)"
echo "  agentic CLI:        ${AGENTIC_CLI}"
echo ""

# ---------------------------------------------------------------------------
# Functions
# ---------------------------------------------------------------------------

register_tools() {
    echo "--> Registering ${TOOL_COUNT} Slurm HPC tools at ${MCP_URL}..."

    # Build curl flags for HTTPS CA verification
    CURL_CA_FLAG=""
    if [ "$SLURM_PROTO" = "https" ]; then
        if [ -f "$SLURM_CA_CERT" ]; then
            CURL_CA_FLAG="--cacert ${SLURM_CA_CERT}"
        else
            CURL_CA_FLAG="-k"
            echo "  WARNING: No CA cert at ${SLURM_CA_CERT}, using -k (insecure)"
        fi
    fi

    # Health check
    HEALTH_URL="${SLURM_PROTO}://${SLURM_MCP_HOST}:${SLURM_MCP_PORT}/health"
    echo "  Checking health at ${HEALTH_URL}..."
    if curl -sf $CURL_CA_FLAG "${HEALTH_URL}" >/dev/null 2>&1; then
        echo "  Slurm MCP server is healthy"
    elif $ENGINE exec slurm_mcp_server curl -sf http://localhost:8002/health >/dev/null 2>&1; then
        echo "  Slurm MCP server is healthy (via container)"
    else
        echo "  WARNING: Slurm MCP server health check failed (may not be running yet)"
    fi

    local pass=0
    local fail=0
    for i in $(seq 0 $((TOOL_COUNT - 1))); do
        local name
        local remote
        local desc
        local schema

        name=$(jq -r ".tools[$i].registered_name" "$REGISTRY_FILE")
        remote=$(jq -r ".tools[$i].remote_name" "$REGISTRY_FILE")
        desc=$(jq -r ".tools[$i].description" "$REGISTRY_FILE")
        schema=$(jq -c ".tools[$i].args_schema" "$REGISTRY_FILE")

        echo -n "  Registering ${name} (remote: ${remote})... "
        if "${AGENTIC_CLI}" tools register "${name}" \
            -d "${desc}" \
            -p mcp \
            -u "${MCP_URL}" \
            --tool-name "${remote}" \
            --args-schema "${schema}" \
            --username "${ADMIN_USER}" \
            --password "${ADMIN_PASS}" >/dev/null 2>&1; then
            echo "OK"
            pass=$((pass + 1))
        else
            echo "FAILED"
            fail=$((fail + 1))
        fi
    done

    echo ""
    echo "Result: ${pass}/${TOOL_COUNT} tools registered successfully"
    [ "$fail" -eq 0 ] || return 1
}

deregister_tools() {
    echo "--> Deregistering ${TOOL_COUNT} Slurm HPC tools..."

    local pass=0
    local fail=0
    for i in $(seq 0 $((TOOL_COUNT - 1))); do
        local name
        name=$(jq -r ".tools[$i].registered_name" "$REGISTRY_FILE")

        echo -n "  Deregistering ${name}... "
        if "${AGENTIC_CLI}" tools delete "${name}" --yes \
            --username "${ADMIN_USER}" \
            --password "${ADMIN_PASS}" >/dev/null 2>&1; then
            echo "OK"
            pass=$((pass + 1))
        else
            echo "FAILED (may not exist)"
            fail=$((fail + 1))
        fi
    done

    echo ""
    echo "Result: ${pass}/${TOOL_COUNT} tools deregistered"
}

verify_tools() {
    echo "--> Verifying Slurm tool registration in Redis..."

    # Pre-flight: check if ENGINE can reach Redis
    if ! $ENGINE exec redis redis-cli PING >/dev/null 2>&1; then
        echo ""
        echo "  WARNING: Cannot reach Redis via '$ENGINE exec redis'."
        echo "  Ensure your user is in the docker group:"
        echo "    sudo usermod -aG docker \$USER && newgrp docker"
        echo ""
        return 1
    fi

    local found=0
    local missing=0
    local schema_warnings=0
    for i in $(seq 0 $((TOOL_COUNT - 1))); do
        local name
        name=$(jq -r ".tools[$i].registered_name" "$REGISTRY_FILE")

        redis_val=$($ENGINE exec redis redis-cli GET "external_tool:${name}" 2>/dev/null || echo "")

        if [ -n "$redis_val" ] && [ "$redis_val" != "(nil)" ]; then
            if echo "$redis_val" | python3 -c "import sys,json; d=json.load(sys.stdin); assert d.get('args_schema') is not None" 2>/dev/null; then
                echo "  + ${name} found in Redis (with args_schema)"
            else
                echo "  ~ ${name} found in Redis (WARNING: missing args_schema)"
                schema_warnings=$((schema_warnings + 1))
            fi
            found=$((found + 1))
        else
            echo "  - ${name} NOT found in Redis"
            missing=$((missing + 1))
        fi
    done

    echo ""
    echo "Result: ${found}/${TOOL_COUNT} tools verified in Redis"
    if [ "$schema_warnings" -gt 0 ]; then
        echo "WARNING: ${schema_warnings} tool(s) missing args_schema. Re-register with: make register-tools"
    fi
    [ "$missing" -eq 0 ] || return 1
}

show_usage() {
    echo "Usage: $0 [register|deregister|verify|help]"
    echo ""
    echo "Commands:"
    echo "  register    Register all ${TOOL_COUNT} Slurm tools with ADEPT (default)"
    echo "  deregister  Remove all ${TOOL_COUNT} Slurm tools from ADEPT"
    echo "  verify      Check that tools exist in Redis"
    echo "  help        Show this message"
    echo ""
    echo "Data source:"
    echo "  ${REGISTRY_FILE}"
    echo "  Generated by: python3 scripts/generate-registration-schemas.py"
    echo ""
    echo "Environment:"
    echo "  KEYCLOAK_URL             (default: http://keycloak:8180) MUST use Docker service name"
    echo "  KEYCLOAK_REALM           (default: master) Keycloak realm"
    echo "  AGENT_GATEWAY_URL        (default: http://localhost:8083) Gateway URL"
    echo "  SLURM_PROTO              (default: http) Protocol: http or https"
    echo "  SLURM_MCP_HOST           (http default: slurm_mcp_server, https default: slurm_nginx_proxy)"
    echo "  SLURM_MCP_PORT           (http default: 8002, https default: 443)"
    echo "  SLURM_CA_CERT            (default: ./certs/ca.crt) CA cert for HTTPS verification"
    echo "  ADMIN_USER               (default: admin) ADEPT admin username"
    echo "  ADMIN_PASS               (default: admin) ADEPT admin password"
    echo "  ENGINE                   (default: docker) Docker engine command"
    echo ""
    echo "IMPORTANT: /etc/hosts must contain:"
    echo "  127.0.0.1 keycloak agent_gateway gateway_registry redis orchestration_service"
    echo ""
    echo "This ensures the agentic CLI can reach Keycloak using the Docker service name,"
    echo "producing JWT tokens with the correct issuer (http://keycloak:8180/realms/master)"
    echo "that the gateway will accept."
    echo ""
    echo "Examples:"
    echo "  $0 register                                                          # HTTP direct to MCP server"
    echo "  SLURM_PROTO=https $0 register                                        # HTTPS via nginx proxy (same host)"
    echo "  SLURM_PROTO=https SLURM_MCP_HOST=10.0.1.50 SLURM_MCP_PORT=9821 $0 register  # HTTPS cross-host"
}

# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

ACTION="${1:-register}"

case "$ACTION" in
    register)
        register_tools
        echo ""
        verify_tools
        ;;
    deregister)
        deregister_tools
        ;;
    verify)
        verify_tools
        ;;
    help|--help|-h)
        show_usage
        ;;
    *)
        echo "Unknown action: ${ACTION}"
        show_usage
        exit 1
        ;;
esac
